def button(text,url,light=False):return f'<a class="button {"light" if light else ""}" href="{url}"><span>{text}</span><span class="button-arrow">↗</span></a>'
def header(page):
 links=''.join(f'<a href="{url}" {"aria-current=page" if page==url else ""}>{name}</a>' for url,name in navitems[1:])
