home=home.replace('href="/kontakt/"><span>Lär känna Southbase</span>', 'href="/om-oss/"><span>Lär känna Southbase</span>')
home=home.replace('01 / 03','').replace('href="mailto:kontakt@southbase.se"','href="/kontakt/"')
